from PIL import Image
im0 = Image.open("/home/robot/captures/side_010.jpg")
im1 = Image.open("/home/robot/captures/side_011.jpg")
px0 = im0.load()
px1 = im1.load()

def brightness(im_px, x, y):
    r,g,b = im_px[x,y]
    return (r+g+b)/3

# Find platen top edge: scan down the center of platen for a bright-to-dark or background-to-platen transition
# First find platen x center by looking for light gray at expected region

def find_platen_span(px, y):
    xs = []
    for x in range(250, 420):
        r,g,b = px[x,y]
        br = (r+g+b)/3
        if br > 160 and abs(r-b) < 25:
            xs.append(x)
    return xs

# search y for platen
for y in range(180, 250):
    xs = find_platen_span(px0, y)
    if len(xs) > 20:
        print(f"unloaded platen y={y} x={xs[0]}-{xs[-1]} w={xs[-1]-xs[0]+1}")
        break
for y in range(180, 260):
    xs = find_platen_span(px1, y)
    if len(xs) > 20:
        print(f"loaded platen y={y} x={xs[0]}-{xs[-1]} w={xs[-1]-xs[0]+1}")
        break

# more precise: for center x, find y where brightness crosses threshold for platen top
def edge_y(px, x, y0, y1, thresh, direction="rise"):
    # subpixel by linear interpolation
    prev = brightness(px, x, y0)
    for y in range(y0+1, y1):
        br = brightness(px, x, y)
        if direction=="rise" and prev < thresh <= br:
            frac = (thresh-prev)/(br-prev) if br!=prev else 0
            return y-1+frac
        if direction=="fall" and prev > thresh >= br:
            frac = (prev-thresh)/(prev-br) if prev!=br else 0
            return y-1+frac
        prev = br
    return None

# platen center x ~ 320
for name, px in [("unloaded", px0), ("loaded", px1)]:
    # average edge over x=305 to 335
    edges = []
    for x in range(305, 336):
        e = edge_y(px, x, 180, 240, 140, "rise")
        if e:
            edges.append(e)
    print(name, "platen top edge y mean", sum(edges)/len(edges), "n", len(edges), "range", min(edges), max(edges))

# yellow top edge
def is_yellow(px, x, y):
    r,g,b = px[x,y]
    return r > 120 and g > 80 and b < 50 and r > b+50

for name, px in [("unloaded", px0), ("loaded", px1)]:
