                print(name, f"yellow top x={x} y={y}")
                break

# spring bottom / hole floor: look at a column in the gap, e.g. x=290 (left gap) for vertical profile
print("\n--- vertical profiles in gap ---")
for x in [288, 292, 348, 352]:
    print(f"\n x={x}")
    for y in range(240, 275, 1):
        r0,g0,b0 = px0[x,y]
        r1,g1,b1 = px1[x,y]
        print(f"  y={y} U=({r0:3d},{g0:3d},{b0:3d}) L=({r1:3d},{g1:3d},{b1:3d}) d={(r1-r0)+(g1-g0)+(b1-b0):+4d}")
